import{_ as e,c as i,o,ae as t}from"./chunks/framework.DYBsrYGD.js";const h=JSON.parse('{"title":"vue（Vue 2 侧概览）","description":"","frontmatter":{},"headers":[],"relativePath":"框架和类库/Vue2/Vue概览/index.md","filePath":"框架和类库/Vue2/Vue概览/index.md"}'),a={name:"框架和类库/Vue2/Vue概览/index.md"};function u(r,l,d,c,n,s){return o(),i("div",null,[...l[0]||(l[0]=[t('<h1 id="vue-vue-2-侧概览" tabindex="-1">vue（Vue 2 侧概览） <a class="header-anchor" href="#vue-vue-2-侧概览" aria-label="Permalink to &quot;vue（Vue 2 侧概览）&quot;">​</a></h1><blockquote><p><strong>Vue 2 与 Vue 3 对照</strong>（生命周期映射、通信/API 差异等）见：<a href="./../../Vue2与Vue3对比/">Vue2与Vue3对比</a>。</p></blockquote><h2 id="生命周期函数-vue-2-选项式" tabindex="-1">生命周期函数（Vue 2 选项式） <a class="header-anchor" href="#生命周期函数-vue-2-选项式" aria-label="Permalink to &quot;生命周期函数（Vue 2 选项式）&quot;">​</a></h2><p>常用钩子：<code>beforeCreate</code>、<code>created</code>、<code>beforeMount</code>、<code>mounted</code>、<code>beforeUpdate</code>、<code>updated</code>、<code>beforeDestroy</code>、<code>destroyed</code>、<code>errorCaptured</code>。</p><p>被 <code>keep-alive</code> 缓存的组件额外具有：<code>activated</code>、<code>deactivated</code>。</p><h2 id="组件间通信-vue-2-常用" tabindex="-1">组件间通信（Vue 2 常用） <a class="header-anchor" href="#组件间通信-vue-2-常用" aria-label="Permalink to &quot;组件间通信（Vue 2 常用）&quot;">​</a></h2><ul><li><strong>props</strong>：父 → 子。</li><li><strong><code>v-bind:xxx.sync</code></strong>：父子双向（绑定 <code>xxx</code> 与 <code>update:xxx</code> 事件）。</li><li><strong>自定义事件</strong>：子 → 父；组件上监听默认多为<strong>自定义事件</strong>，监听原生 DOM 事件常需 <strong><code>.native</code></strong>。</li><li><strong>Vuex</strong>：多组件共享状态（兄弟、祖孙等场景常见）。</li><li><strong><code>v-model</code></strong>：在 Vue 2 组件上常见为 <strong><code>value</code> + <code>input</code></strong>（与具体封装有关）。</li><li><strong>插槽</strong>：默认插槽、具名插槽、作用域插槽。</li><li><strong>全局事件总线</strong>：如 <code>$bus</code>（自建）。</li><li><strong><code>$parent</code> / <code>$children</code> / <code>$refs</code></strong>：获取实例或子组件。</li><li><strong><code>$attrs</code> / <code>$listeners</code></strong>：透传属性与监听（Vue 2 中二者分离）。</li><li><strong><code>provide</code> / <code>inject</code></strong>：跨层级注入。</li><li><strong>离线存储</strong>：<code>localStorage</code>、<code>sessionStorage</code>。</li></ul><h2 id="全局状态管理工具" tabindex="-1">全局状态管理工具 <a class="header-anchor" href="#全局状态管理工具" aria-label="Permalink to &quot;全局状态管理工具&quot;">​</a></h2><h3 id="vuex" tabindex="-1">Vuex <a class="header-anchor" href="#vuex" aria-label="Permalink to &quot;Vuex&quot;">​</a></h3><p>一个集中式状态管理方案，通常用于管理多个组件共享的状态数据。</p><p>开发时需要定义主模块和其他分模块</p><p>主模块主要定义 modules 属性用来汇总其他分模块</p><p>其他分模块主要定义 <code>state</code>、<code>getters</code>、<code>actions</code>、<code>mutations</code>、<code>namespaced</code>。</p><ul><li>state 模块管理的状态数据</li><li>getters 只读计算属性数据</li><li>actions 一般用来与服务器进行交互的函数，比如：发送请求</li><li>mutations 直接更新数据的函数</li><li>namespaced 的值为 true，开启命名空间，这样每个 vuex 模块的内容就被隔离，不会互相影响。</li></ul><p>组件读取/更新 vuex 数据有两种方式，一种通过<code>$store</code>，一种 map 函数形式</p><p>一般如果数据只用一两次，我会用$store，比较简单。数据比较频繁使用，用 map 函数形式</p><h3 id="pinia" tabindex="-1">Pinia <a class="header-anchor" href="#pinia" aria-label="Permalink to &quot;Pinia&quot;">​</a></h3><p>一个集中式状态管理方案，通常用于管理多个组件共享的状态数据。</p><p>相对于 Vuex 来说，pinia 优点：</p><ul><li>没有 mutations （流程更简洁）</li><li>Typescript 支持更友好</li><li>pinia 模块定义即可使用，不用汇总</li></ul><p>开发时需要定义主模块和其他分模块：主模块定义好后，就定义分模块即可，不用汇总</p><p>分模块主要由以下内容：</p><ul><li>state 模块管理的状态数据</li><li>getters 只读计算属性数据</li><li>actions 与服务器进行交互（发送请求），同时更新数据</li></ul><p>组件引入分模块暴露的 useXxxStore 函数，得到 Store 对象，即可操作数据和方法了</p><ul><li>一般如果我需要直接更新一个数据：就直接操作数据即可</li><li>如果我需要直接更新多个数据：store.$patch 方法更新数据</li><li>如果我需要更新数据并且发送请求：就需要定义 action 函数，通过 store 调用 action 函数来更新</li></ul><p>（<strong>与 Vue 3 的差异清单</strong>已迁至 <a href="./../../Vue2与Vue3对比/综合差异速查.html">综合差异速查</a>。）</p><h2 id="vue的指令" tabindex="-1">Vue的指令 <a class="header-anchor" href="#vue的指令" aria-label="Permalink to &quot;Vue的指令&quot;">​</a></h2><ol><li>常用指令</li></ol><ul><li>v-if / v-else-if / v-else 条件渲染（控制元素的显示和隐藏）</li><li>v-show 条件渲染（控制元素的显示和隐藏） <ul><li>v-if 和 v-show 区别： <ul><li>v-if 隐藏时，销毁元素（卸载组件）</li><li>v-show 隐藏时，通过 display:none 来隐藏的</li><li>结论：频繁切换用 v-show，不频繁用 v-if</li></ul></li></ul></li><li>v-for 遍历展示（列表渲染） <ul><li>key 属性作用：在 diff 算法中，尽可能复用相同 key 的元素，更新性能更好</li><li>key 属性取值：一般用 id，用 index 可能导致更新性能不好</li><li><strong>Vue 2</strong> 中同节点 <strong><code>v-for</code> 优先级高于 <code>v-if</code></strong>（不建议同节点混用；与 Vue 3 的差异见 <a href="./../../Vue2与Vue3对比/综合差异速查.html">综合差异速查</a>）</li></ul></li><li>v-on 绑定事件 @ <ul><li>事件修饰符 .prevent .stop .once .self</li><li>按键修饰符 .enter .13</li></ul></li><li>v-model 双向数据绑定 <ul><li>双向数据绑定原理 <ul><li>给普通 input 元素（text）绑定，绑定的是 value 属性和 input 事件</li><li>给单选（radio）或多选（checkout）绑定，绑定的是 checked 属性和 change 事件</li><li>给下拉列表（select）绑定，绑定的是 value 属性和 change 事件</li><li>给组件绑定：在 <strong>Vue 2</strong> 中常与<strong>普通表单元素</strong>类似（<code>value</code> + <code>input</code> 等，依组件实现而定）</li></ul></li></ul></li><li>v-bind 单向数据绑定（强制绑定数据） :</li><li>v-slot 插槽 # <ul><li>默认插槽、具名插槽和作用域插槽</li></ul></li></ul><ol start="2"><li>不常用指令</li></ol><ul><li>v-text 设置元素 textContent</li><li>v-html 设置元素 innerHTML</li><li>v-once 元素只解析渲染一次，后续再也不变了</li><li>v-pre 跳过解析，直接渲染最原始的内容</li><li>v-cloak 防止解析时渲染表达式(用于隐藏尚未完成编译的 DOM 模板。)</li></ul><h2 id="vuerouter" tabindex="-1">VueRouter <a class="header-anchor" href="#vuerouter" aria-label="Permalink to &quot;VueRouter&quot;">​</a></h2><ol><li>概念 用来实现 Vue 的单页面应用（single page web application，SPA）。</li></ol><p>单页面应用特点：</p><ul><li>整个应用只有一个完整页面，所有更新只是这个页面的局部渲染</li><li>点击页面链接不会刷新整个页面，只会更新浏览历史记录和页面局部更新</li></ul><ol start="2"><li>路由两种模式</li></ol><ul><li>hash <ul><li>特点 <ul><li>hash 路径带 #，# 后面的值（路由路径）不会提交到 server 端；</li><li>hash 可以改变 url ，准确来说改变的是 # 后面的值，页面不会刷新；</li><li>兼容性更好, IE6+。</li></ul></li><li>原理 <ul><li>hash 通过 window.location.hash 的方式，实现路由跳转的功能。</li><li>hash 通过 window.onhashchange 的方式，来监听 hash 的改变，借此实现无刷新跳转的功能。</li></ul></li></ul></li><li>history <ul><li>特点 <ul><li>history 路径不带 #，更美观。</li><li>history 可以改变 url ，改变的是整个 url，页面不会刷新；</li><li>兼容性稍差, IE10+；</li><li>页面刷新时，history 可能会出现 404 问题。</li></ul></li><li>原理 <ul><li>history 通过 window.history.pushState / replaceState 等方式，实现路由跳转的功能。</li><li>history 通过 window.onpopstate 的方式，来监听 url 的改变，借此实现无刷新跳转的功能。</li></ul></li></ul></li></ul><ol start="3"><li>基本内容</li></ol><ul><li>提供两个组件 <ul><li>router-link 用来路由跳转（声明式导航）</li><li>router-view 用来加载渲染路由组件</li></ul></li><li>提供两个属性 <ul><li>$router 用来路由跳转（编程式导航）</li><li>$route 用来获取路由参数和路由路径</li></ul></li></ul><ol start="4"><li>路由跳转两种方式</li></ol><ul><li>声明式导航 router-link</li><li>编程式导航 this.$router.push/replace/go</li></ul><ol start="5"><li>路由传参</li></ol><ul><li>query</li><li>params</li><li>meta</li></ul><ol start="6"><li>路由导航守卫</li></ol><ul><li>全局路由导航守卫 <ul><li>beforeEach</li><li>afterEach</li></ul></li><li>路由独享守卫</li><li>组件独享守卫</li></ul><p>最重要的是全局路由导航守卫的 beforeEach</p><p>主要用来：权限管理功能，控制用户的访问权限</p><ol start="7"><li>路由懒加载</li></ol><p>通过 import 动态加载组件，实现组件懒加载</p><p>内部做了两件事：</p><ul><li>代码分割：将路由组件单独打包成一个 js 文件</li><li>按需加载：需要使用这个路由组件时，才会加载对应的 js 文件</li></ul><h2 id="nexttick-方法的原理-vue-2" tabindex="-1">nextTick 方法的原理（Vue 2） <a class="header-anchor" href="#nexttick-方法的原理-vue-2" aria-label="Permalink to &quot;nextTick 方法的原理（Vue 2）&quot;">​</a></h2><blockquote><p>Vue 3 中 <code>nextTick</code> 行为与动机对照见 <a href="./../../Vue2与Vue3对比/综合差异速查.html#nexttick-差异原理层面">综合差异速查</a>。</p></blockquote><ol><li>定义一个数组（callbacks）用来存储回调函数</li><li>定义一个用来遍历数组，执行回调函数的方法（flushCallbacks）</li><li>定义一个用来将执行回调函数的方法添加到异步队列去的方法（timerFunc）</li></ol><ul><li>这个方法内部会通过 4 种方式来操作：Promise、MutationObserver、setImmediate、setTimeout</li><li>会从上到下依次判断来选择，一旦选择前面的方案，后面就不看了</li></ul><ol start="4"><li><p>到此准备工作完成了，接下来组件会调用 nextTick 方法</p></li><li><p>调用 nextTick 方法时，会将回调函数添加到数组（callbacks）中，在通过 timerFunc 将执行回调函数的方法 flushCallbacks 添加到异步队列等待将来执行</p></li><li><p>等主线程执行完所有同步代码，就会执行异步代码，此时会就执行 flushCallbacks 函数</p></li><li><p>执行 flushCallbacks 函数就会遍历所有回调函数依次执行</p></li></ol><p>总结：</p><p>所以 nextTick 方法的真正理解就是将回调函数添加到异步队列中，等待将来执行。</p><p>它之所以可以等 DOM 元素渲染完成才触发回调函数，是因为我们先更新响应式数据，此时内部会将更新用户界面的方法通过 nextTick 添加到异步队列去，在调用 nextTick 方法，会将其他代码也添加到异步队列去，队列先进先出，所以先更新用户界面，在执行其他代码，此时就能操作更新后的 DOM 元素了</p><h2 id="双向数据绑定原理" tabindex="-1">双向数据绑定原理 <a class="header-anchor" href="#双向数据绑定原理" aria-label="Permalink to &quot;双向数据绑定原理&quot;">​</a></h2><p>v-model 主要用于双向数据绑定（收集表单数据），它给元素绑定时，不同元素做法不一样：</p><ol><li>如果是文本类型元素（input 和 textarea）：绑定 value 属性和 input 事件；</li><li>如果是单选或多选元素（input type=&quot;checkbox&quot; 和 input type=&quot;radio&quot;）：绑定 checked 属性和 change 事件；</li><li>如果是下拉列表元素（select）：绑定 value 属性和 change 事件；</li><li>如果不是上述这些元素（比如组件），会按照文本类型元素处理。</li></ol><h2 id="响应式原理-vue-2" tabindex="-1">响应式原理（Vue 2）<a name="响应式原理"></a> <a class="header-anchor" href="#响应式原理-vue-2" aria-label="Permalink to &quot;响应式原理（Vue 2）&lt;a name=&quot;响应式原理&quot;&gt;&lt;/a&gt;&quot;">​</a></h2><p>完整分点说明见：<a href="./../Vue2/响应式原理.html">Vue2 响应式原理</a>（数据代理、数据劫持、首次渲染与更新链路）。</p><h2 id="虚拟-dom-与-vue-3-的对照" tabindex="-1">虚拟 DOM：与 Vue 3 的对照 <a class="header-anchor" href="#虚拟-dom-与-vue-3-的对照" aria-label="Permalink to &quot;虚拟 DOM：与 Vue 3 的对照&quot;">​</a></h2><p>Vue 2 / Vue 3 在虚拟 DOM 与编译策略上的差异见：<a href="./../../Vue2与Vue3对比/综合差异速查.html#虚拟-dom-与更新策略对照">综合差异速查</a>。</p><h2 id="vue2中虚拟domdiff算法" tabindex="-1">Vue2中虚拟DOMDiff算法 <a class="header-anchor" href="#vue2中虚拟domdiff算法" aria-label="Permalink to &quot;Vue2中虚拟DOMDiff算法&quot;">​</a></h2><ol><li>Diff 算法简述</li></ol><p>初始化渲染阶段会生成一个虚拟 DOM 树（旧树），更新数据时会生成一个新的虚拟 DOM 树，新旧虚拟 DOM 树进行比较，找到不同的内容，从而更新，这就是虚拟 DOM Diff 算法做的事情</p><ol start="2"><li>虚拟 DOM 树简述</li></ol><p>虚拟 DOM 树就是一个对象，这个对象通过特定属性代表真实 DOM 元素的信息，比如：tag 代表元素标签，data 代表元素属性，children 代表子元素</p><ol start="3"><li>Diff 算法详细流程</li></ol><p>Diff 算法一共会经历三个函数：patch、patchVnode、updateChildren</p><p>其中最重要的是 updateChildren 方法：</p><p>它是对相同层级的所有子节点进行 diff（比较），整体流程是从两端到中间遍历，一个一个元素进行比较，从而更新。</p><p>具体来说：</p><ul><li><p>定义 4 个指针，分别指向旧的虚拟 DOM 树开头，也叫做旧前，指向旧的虚拟 DOM 树结尾，叫做旧后，新的虚拟 DOM 树开头，叫做新前，新的虚拟 DOM 树结尾，叫做新后</p></li><li><p>整个遍历过程（详细版本）：</p><ul><li>判断旧前元素是否存在，不存在就更新下标（旧前++），存在就下一步</li><li>判断旧后元素是否存在，不存在就更新下标（旧后--）存在就下一步</li><li>判断旧前和新前元素是否一致（sameVnode：看 key 和 tag），如果一致就会进一步比较（patchVnode），（新前旧前）下标++，不一致就下一步</li><li>判断旧后和新后元素是否一致（sameVnode：看 key 和 tag），如果一致就会进一步比较（patchVnode），（新后旧后）下标--，不一致就下一步</li><li>判断旧前和新后元素是否一致（sameVnode：看 key 和 tag），如果一致就会进一步比较（patchVnode），更新下标（新后--旧前++），移动 DOM 元素位置（将旧前插入到旧后的后面），不一致就下一步</li><li>判断旧后和新前元素是否一致（sameVnode：看 key 和 tag），如果一致就会进一步比较（patchVnode），更新下标（旧后--新前++），移动 DOM 元素位置（将旧后插入到旧前的前面），不一致就下一步</li><li>看 key，提取旧树剩下的子元素的 key 属性，判断新前节点的 key 在不在旧树 key 中，存在就移动 DOM 元素位置，不存在创建新前元素插入页面，更新下标（新前++）</li></ul></li><li><p>整个遍历过程（简化版本）：</p><ul><li>旧前新前</li><li>旧后新后</li><li>旧前新后</li><li>旧后新前</li><li>看 key</li><li>其中 旧前新后 旧后新前 看 key 更新 DOM 元素后，还需要移动 DOM 元素位置</li></ul></li></ul><p>到此更新基本完成。（后面还有两个流程，也可以说）</p><h2 id="如何理解vue中的模板编译原理" tabindex="-1">如何理解Vue中的模板编译原理？ <a class="header-anchor" href="#如何理解vue中的模板编译原理" aria-label="Permalink to &quot;如何理解Vue中的模板编译原理？&quot;">​</a></h2><ul><li>这个问题的核心是如何将template转换成render函数。</li><li>将template模块转换成ast语法书 - parserHTML</li><li>对静态语法做标记（某些节点不改变）</li><li>重新生成代码 - codeGen,使用with语法包裹字符串</li></ul>',80)])])}const v=e(a,[["render",u]]);export{h as __pageData,v as default};
